"use client";

import * as React from "react";
import { cn } from "../../lib/utils";

// Skeleton: generated by UIX from the design system. Same variants and sizes as the Figma component.

function Bar({ className }: { className?: string }) {
  return <div aria-hidden className={cn("animate-pulse rounded-sm bg-muted", className)} />;
}

export interface SkeletonProps extends React.HTMLAttributes<HTMLDivElement> {
  /** "block" is a bare placeholder you size with className; the others are ready-made layouts. */
  type?: "block" | "text" | "avatar" | "card" | "list-item";
}

function layoutFor(type: SkeletonProps["type"]) {
  if (type === "text") {
    return (
      <div className="flex flex-col gap-2">
        <Bar className="h-3 w-full" />
        <Bar className="h-3 w-5/6" />
        <Bar className="h-3 w-1/2" />
      </div>
    );
  }
  if (type === "avatar") {
    return (
      <div className="flex items-center gap-3">
        <Bar className="size-10 shrink-0 rounded-full" />
        <div className="flex flex-col gap-1-5">
          <Bar className="h-3 w-[120px]" />
          <Bar className="h-2.5 w-20" />
        </div>
      </div>
    );
  }
  if (type === "card") {
    return (
      <div className="flex flex-col gap-3 p-4 bg-surface border border-line-subtle rounded-xl">
        <Bar className="w-full rounded-md h-[120px]" />
        <Bar className="h-3.5 w-3/5" />
        <Bar className="h-2.5 w-full" />
        <Bar className="h-2.5 w-4/5" />
      </div>
    );
  }
  if (type === "list-item") {
    return (
      <div className="flex items-center gap-3 p-3">
        <Bar className="size-8 shrink-0 rounded-md" />
        <div className="flex flex-1 flex-col gap-1-5">
          <Bar className="h-3 w-3/5" />
          <Bar className="h-2.5 w-2/5" />
        </div>
        <Bar className="h-5 w-12 rounded-full" />
      </div>
    );
  }
  return <Bar className="h-4 w-full" />;
}

const Skeleton = React.forwardRef<HTMLDivElement, SkeletonProps>(({ className, type = "block", ...props }, ref) =>
  type === "block" ? (
    <div ref={ref} data-slot="skeleton" data-kind="surface" role="status" aria-busy="true" aria-label="Loading" className={cn("skin-quiet animate-pulse rounded-sm bg-muted h-4 w-full", className)} {...props} />
  ) : (
    <div ref={ref} data-slot="skeleton" data-kind="surface" role="status" aria-busy="true" aria-label="Loading" className={cn("skin-quiet w-full", className)} {...props}>
      {layoutFor(type)}
    </div>
  ),
);
Skeleton.displayName = "Skeleton";

export { Skeleton };
